[CmdletBinding()]
param(
  [Parameter(Mandatory=$true)][string]$Projeto,
  [switch]$AtualizarPrisma
)
$ErrorActionPreference = 'Stop'
Write-Host "`n============================================================" -ForegroundColor Cyan
Write-Host " ROBO AVALIADOR - CORRECAO CONTROLADA DE CHAUVENET" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
if (!(Test-Path -LiteralPath $Projeto -PathType Container)) { throw "Projeto nao encontrado: $Projeto" }
$root = (Resolve-Path -LiteralPath $Projeto).Path
$work = Join-Path $env:TEMP ("RoboAvaliador_CHAUVENET_" + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $work -Force | Out-Null
$zip = Join-Path $work 'correcao.zip'
try {
  $b64 = @'

'@
  [IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(($b64 -replace '\s','')))
  Expand-Archive -LiteralPath $zip -DestinationPath $work -Force
  $patch = Join-Path $work 'CORRECAO_CHAUVENET_20261005'
  if (!(Test-Path -LiteralPath $patch -PathType Container)) { throw "Pacote interno de correcao nao encontrado." }
  $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
  $backup = Join-Path $root ("backup_chauvenet_" + $stamp)
  New-Item -ItemType Directory -Path $backup -Force | Out-Null
  $files = @(
    'backend/src/routes/avaliacao.routes.ts',
    'backend/src/services/ReportService.ts',
    'backend/src/services/safety-primitives.ts',
    'backend/src/engines/RuleEngine.ts',
    'backend/src/engines/SaneamentoEngine.ts',
    'backend/src/engines/safety-primitives.ts',
    'backend/prisma/schema.prisma',
    'backend/tests/SaneamentoEngine.test.ts',
    'backend/tests/ChauvenetGovernance.test.ts'
  )
  foreach ($rel in $files) {
    $src = Join-Path $patch $rel
    if (Test-Path -LiteralPath $src -PathType Leaf) {
      $dst = Join-Path $root $rel
      if (Test-Path -LiteralPath $dst -PathType Leaf) {
        $bd = Join-Path $backup $rel
        New-Item -ItemType Directory -Path (Split-Path $bd -Parent) -Force | Out-Null
        Copy-Item -LiteralPath $dst -Destination $bd -Force
      }
      New-Item -ItemType Directory -Path (Split-Path $dst -Parent) -Force | Out-Null
      Copy-Item -LiteralPath $src -Destination $dst -Force
      Write-Host ("OK  {0}" -f $rel) -ForegroundColor Green
    } else { throw "Arquivo da correcao ausente no pacote: $rel" }
  }
  if ($AtualizarPrisma) {
    Write-Host "`nAtualizando Prisma (generate + db push; sem reset/seed)..." -ForegroundColor Yellow
    Push-Location $root
    try {
      npm --prefix backend exec prisma generate
      if ($LASTEXITCODE -ne 0) { throw "prisma generate falhou." }
      npm --prefix backend exec prisma db push
      if ($LASTEXITCODE -ne 0) { throw "prisma db push falhou." }
    } finally { Pop-Location }
  }
  Write-Host "`nCORRECAO APLICADA COM SUCESSO." -ForegroundColor Green
  Write-Host ("Backup: {0}" -f $backup) -ForegroundColor DarkCyan
  Write-Host "Nenhum reset, seed, recalculo, snapshot ou emissao foi executado." -ForegroundColor Cyan
} catch {
  Write-Error $_
  exit 1
} finally {
  Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
}
